  ('Ping Pong at the Community Hall', 'Downstairs in the Gabriola Community Hall on Tuesday evenings from 6:30pm-8:30pm', '2026-12-01'::date, '2026-12-01'::date, '18:30:00'::time, '20:30:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/ping-pong-at-the-community-hall-1886910', false),
  ('AA Gathering at the Community Hall - Women Only', 'AA Group meets downstairs every Wednesday morning at the Gabriola Community Hall from 9am-10am', '2026-12-02'::date, '2026-12-02'::date, '09:00:00'::time, '10:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-gathering-at-the-community-hall-women-only-1895672', true),
  ('Shut Up & Write! at the Gabriola Library', 'A 2-hour session of silent writing on Wednesdays at the Gabriola Library. No discussions, just quick introductions then work silently on your writing project. 10am-12pm. Optional discussion period from 12pm-12:30pm', '2026-12-02'::date, '2026-12-02'::date, '10:00:00'::time, '12:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/shut-up-write-at-the-gabriola-library-1887002', true),
  ('Mom''s Group at the Gabriola Fellowship Church', 'Mom''s Group meeting every Wednesday at the Gabriola Fellowship Church from 10:30am - 1:30pm. We host a supportive and welcoming space for moms to connect, share experiences, and build lasting friendships. Whether you''re a new mom or seasoned pro, come join us for encouragement, laughter, and real talk about motherhood', '2026-12-02'::date, '2026-12-02'::date, '10:30:00'::time, '13:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/mom-s-group-at-the-gabriola-fellowship-church-1901044', true),
  ('Meet for Meditation at the Gabriola Library', 'Meet for meditation on Wednesdays at the Gabriola Library from 1pm-2pm. Art of Living teacher, Susan Murray, will lead you through a wonderfully relaxing session no matter your experience level. No registration required', '2026-12-02'::date, '2026-12-02'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/meet-for-meditation-at-the-gabriola-library-1887048', true),
