  ('Gabriola Players Pantomime', 'Listed on the Gabriola Community Hall calendar (a room booking calendar). Times shown are the booking and may include setup. Check with the organizer for event hours.', '2026-12-03'::date, '2026-12-06'::date, NULL::time, NULL::time, true, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Community Hall calendar', 'https://gabriolacommunityhall.com/event-calendar/', false),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-12-04'::date, '2026-12-04'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895499', true),
  ('Coffee & Lunch Social at the Christ Church', 'Every Friday from 10:30am to 12:30pm at Christ Church Gabriola. This is a great time for our community to get together. The soup and desserts are always amazing and each week we have musicians to entertain us. A non-religious event. Also supported by PHC', '2026-12-04'::date, '2026-12-04'::date, '10:30:00'::time, '12:30:00'::time, false, 'Christ Church', 'Christ Church', '2600 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/coffee-lunch-social-at-the-christ-church-1903256', true),
  ('Adult Day Program (PHC)', 'Provides engaging therapeutic activities for individuals experiencing physical, cognitive or social challenges in a safe, supervised environment. Our person-centered programs are developed to offer an opportunity for participants to connect with each other, while also offering respite for caregivers. Dates: Mondays and Fridays, 11:30am-2:30pm. Location: Rollo Seniors Centre, 685 North Rd. Age: 60+ (flexible). Cost: FREE or by donation. Registration required. Participants must complete an Island Health intake assessment. For any questions, please contact seniorsmanager@phcgabriola.org', '2026-12-04'::date, '2026-12-04'::date, '11:30:00'::time, '14:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/adult-day-program-phc-1884590', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-12-04'::date, '2026-12-04'::date, '12:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1895823', true),
