  ('Nintendo Switch Time at the Gabriola Library', 'Fridays from 2:30pm-4:45pm at the Gabriola Library. All year round, drop-in and play Nintendo Switch on our giant screen in the meeting room. We have lots of games to choose from or bring your own from home. Best for ages 7+. NO ADULTS PLEASE, for kids only', '2026-12-04'::date, '2026-12-04'::date, '14:30:00'::time, '16:45:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/nintendo-switch-time-at-the-gabriola-library-1896121', true),
  ('Parkinson''s Group at the Rollo Centre', 'We meet Fridays from 2:45pm-4:15pm to share briefly and support each other, and then join in professionally-led exercises designed for people with Parkinson''s Disease and pitched to our level (mostly seated). Care-givers very welcome! Seated Tai Chi every 4th Friday', '2026-12-04'::date, '2026-12-04'::date, '14:45:00'::time, '16:15:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/parkinson-s-group-at-the-rollo-centre-1895973', true),
  ('Burger and Darts Night at the Gabriola Golf Club', 'Burger and darts night at the Gabriola Golf Club on Fridays. Burgers from 5pm-7pm. Darts from 7pm', '2026-12-04'::date, '2026-12-04'::date, '17:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/burger-and-darts-night-at-the-gabriola-golf-club-1886084', true),
