  ('Palette People Bizarre Bazaar', 'Listed on the Rollo Centre calendar (a room booking calendar). Times shown are the booking and may include setup. Check with the organizer for event hours.', '2026-12-05'::date, '2026-12-05'::date, '09:00:00'::time, '17:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Rollo Centre calendar', 'https://www.gabriolaseniorscentre.com/activities', false),
