  ('Nintendo Switch Time at the Gabriola Library', 'Fridays from 2:30pm-4:45pm at the Gabriola Library. All year round, drop-in and play Nintendo Switch on our giant screen in the meeting room. We have lots of games to choose from or bring your own from home. Best for ages 7+. NO ADULTS PLEASE, for kids only', '2027-01-08'::date, '2027-01-08'::date, '14:30:00'::time, '16:45:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/nintendo-switch-time-at-the-gabriola-library-1896126', true),
  ('Parkinson''s Group at the Rollo Centre', 'We meet Fridays from 2:45pm-4:15pm to share briefly and support each other, and then join in professionally-led exercises designed for people with Parkinson''s Disease and pitched to our level (mostly seated). Care-givers very welcome! Seated Tai Chi every 4th Friday', '2027-01-08'::date, '2027-01-08'::date, '14:45:00'::time, '16:15:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/parkinson-s-group-at-the-rollo-centre-1895978', true),
  ('Burger and Darts Night at the Gabriola Golf Club', 'Burger and darts night at the Gabriola Golf Club on Fridays. Burgers from 5pm-7pm. Darts from 7pm', '2027-01-08'::date, '2027-01-08'::date, '17:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/burger-and-darts-night-at-the-gabriola-golf-club-1886089', true),
  ('Family StoryTime at the Gabriola Library', 'Family storytime on Saturdays at the Gabriola Library from 11am-11:30am. All ages welcome', '2027-01-09'::date, '2027-01-09'::date, '11:00:00'::time, '11:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/family-storytime-at-the-gabriola-library-1887277', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2027-01-10'::date, '2027-01-10'::date, '19:00:00'::time, '20:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1896078', true),
  ('Adult Day Program (PHC)', 'Provides engaging therapeutic activities for individuals experiencing physical, cognitive or social challenges in a safe, supervised environment. Our person-centered programs are developed to offer an opportunity for participants to connect with each other, while also offering respite for caregivers. Dates: Mondays and Fridays, 11:30am-2:30pm. Location: Rollo Seniors Centre, 685 North Rd. Age: 60+ (flexible). Cost: FREE or by donation. Registration required. Participants must complete an Island Health intake assessment. For any questions, please contact seniorsmanager@phcgabriola.org', '2027-01-11'::date, '2027-01-11'::date, '11:30:00'::time, '14:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/adult-day-program-phc-1884595', true),
  ('Line Dancing at the Community Hall', 'Line dancing on Monday evenings from 4pm-6pm at the Gabriola Community Hall', '2027-01-11'::date, '2027-01-11'::date, '16:00:00'::time, '18:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/line-dancing-at-the-community-hall-1887609', true),
  ('Beginner Ukulele Instruction and Singalong', 'Downstairs in the Gabriola Community Hall on Monday evenings from 6pm-8pm. Beginner ukulele: 6-7pm. Sing along and play along: 7-8pm (with a uke or whatever!). Suggested donation = $5', '2027-01-11'::date, '2027-01-11'::date, '18:00:00'::time, '20:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/beginner-ukulele-instruction-and-singalong-1887104', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2027-01-11'::date, '2027-01-11'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900632', true),
  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2027-01-11'::date, '2027-01-11'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887565', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2027-01-11'::date, '2027-01-11'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884651', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2027-01-12'::date, '2027-01-12'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895510', true),
  ('Soup Social (PHC)', 'Soup Socials provide delicious and nutritional meals in a casual setting. This is an event within the community to share a meal which fosters social connection and strengthens relationships. Join us and see what interesting conversation you can engage in with your fellow neighbors. Drop-in, all ages. Dates: Tuesdays, 11am-1pm. Location: Summer: Commons (main floor), 675 North Rd. Winter: Fellowship Church, 775 Church St (approx second week of Oct). Cost: FREE or by donation', '2027-01-12'::date, '2027-01-12'::date, '11:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/soup-social-phc-1884350', true),
  ('Lego Club at the Gabriola Library', 'Tuesdays at the Gabriola Library from 3pm-5pm. Drop in to the meeting room and use our mountains of Lego to let your imagination fly! Challenge cards will inspire your creations. Open to all ages', '2027-01-12'::date, '2027-01-12'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/lego-club-at-the-gabriola-library-1895595', true),
  ('Ping Pong at the Community Hall', 'Downstairs in the Gabriola Community Hall on Tuesday evenings from 6:30pm-8:30pm', '2027-01-12'::date, '2027-01-12'::date, '18:30:00'::time, '20:30:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/ping-pong-at-the-community-hall-1886916', true),
  ('AA Gathering at the Community Hall - Women Only', 'AA Group meets downstairs every Wednesday morning at the Gabriola Community Hall from 9am-10am', '2027-01-13'::date, '2027-01-13'::date, '09:00:00'::time, '10:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-gathering-at-the-community-hall-women-only-1895678', true),
  ('Gabriola Quilters at the Rollo Centre', 'We meet the 2nd, 4th, and 5th Wednesdays from 9:30am-4:00pm in the large room at the Rollo Centre. We are a group of individuals who get together to share ideas, work on projects, our own or a group project, and socialize. We love to play with colours and fabric. Members'' skill range from beginner to very experienced. Some members are also fiber artists, some do other forms of needle crafts to be incorporated into their quilts, or while in between projects. Primarily, we work on our own projects. Occasionally we may be involved as a group in projects that benefit the community. The latest example being the Sunflower quilt for PHC.Membership Fees: $20/calendar year - which covers the storage locker rental with some left over to cover other expenses such as our annual show and sale. There is a $2 activity fee paid to the GSCA each time a member attends. Drop-ins are always welcome. The first visit is free and subsequent visits are $5', '2027-01-13'::date, '2027-01-13'::date, '09:30:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-quilters-at-the-rollo-centre-1896332', true),
  ('Shut Up & Write! at the Gabriola Library', 'A 2-hour session of silent writing on Wednesdays at the Gabriola Library. No discussions, just quick introductions then work silently on your writing project. 10am-12pm. Optional discussion period from 12pm-12:30pm', '2027-01-13'::date, '2027-01-13'::date, '10:00:00'::time, '12:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/shut-up-write-at-the-gabriola-library-1887008', true),
  ('Mom''s Group at the Gabriola Fellowship Church', 'Mom''s Group meeting every Wednesday at the Gabriola Fellowship Church from 10:30am - 1:30pm. We host a supportive and welcoming space for moms to connect, share experiences, and build lasting friendships. Whether you''re a new mom or seasoned pro, come join us for encouragement, laughter, and real talk about motherhood', '2027-01-13'::date, '2027-01-13'::date, '10:30:00'::time, '13:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/mom-s-group-at-the-gabriola-fellowship-church-1901050', true),
  ('Meet for Meditation at the Gabriola Library', 'Meet for meditation on Wednesdays at the Gabriola Library from 1pm-2pm. Art of Living teacher, Susan Murray, will lead you through a wonderfully relaxing session no matter your experience level. No registration required', '2027-01-13'::date, '2027-01-13'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/meet-for-meditation-at-the-gabriola-library-1887054', true),
  ('Tech-Help Wednesdays at the Gabriola Library', 'Wednesdays from 3pm-5pm at the Gabriola Library. Let us help you figure out your device issues. Whether it''s your laptop, tablet, eReader, or phone - we will do what we can to reduce your frustrations!Please bring your device, library card, and any passwords you may need. to book your free, 30-minute tech appointment', '2027-01-13'::date, '2027-01-13'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tech-help-wednesdays-at-the-gabriola-library-1895912', true),
  ('Youth Group at the Gabriola Fellowship Church', 'Youth group on Wednesdays from 4:30pm to 6:30pm at the Gabriola Fellowship Church', '2027-01-13'::date, '2027-01-13'::date, '16:30:00'::time, '18:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/youth-group-at-the-gabriola-fellowship-church-1903090', true),
  ('Games Night at the Gabriola Golf Club', 'Games night at the Gabriola Golf Club on Wednesdays from 6pm-10pm. Poker, cards, board games with expanded menu', '2027-01-13'::date, '2027-01-13'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/games-night-at-the-gabriola-golf-club-1886043', true),
  ('Chess at the Rollo Centre', 'Everyone is welcome to drop in for a game of chess on Wednesdays from 7-9pm. We have a regular turnout of roughly 8-10 players (and growing). All ages and levels are welcome. Bring your own board if you like, but we have plenty of the club-style sets available. A $2 activity for Rollo members, $5 drop-in fee for non-members. Play is informal and tea and cookies are provided', '2027-01-13'::date, '2027-01-13'::date, '19:00:00'::time, '21:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/chess-at-the-rollo-centre-1880473', true),
  ('Tea Thursdays at the Gabriola Library', 'Enjoy a cup of tea (or spa water on hot days!) all day on Thursdays (10am-7pm), thanks to the Friends of the Gabriola Library', '2027-01-14'::date, '2027-01-14'::date, '10:00:00'::time, '19:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tea-thursdays-at-the-gabriola-library-1886871', true),
  ('French Conversation Group at the Gabriola Library', 'Come speak French with us on Thursdays at the Gabriola Library from 1pm-2pm. No preparation is necessary. All levels are welcome. We talk about anything and everything. Venez parler français avec nous le jeudi, de 13 h à 14 h. Aucune préparation nécessaire. Tous les niveaux sont bienvenus. On parle de tout et de rien', '2027-01-14'::date, '2027-01-14'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/french-conversation-group-at-the-gabriola-library-1887154', true),
  ('Gabriola Basketry Group at the Rollo Centre', 'We are an enthusiastic group of artisans who meet every second Thursday at 1:00pm-4:00pm in the small room at the Rollo Centre for an afternoon of basketry. You can check out the Rollo Activity Calendar online or email Marylyn to find out when the next meeting is. The group started meeting and creating in 2002 on Gabriola. Currently we have eight members on Gabriola and about the same number in Nanaimo. Three of our original group are still actively involved in basket making after 23 years!Over the past few years we have jointly facilitated basketry workshops which helps to increase our member numbers. There are no workshops planned at this time. Contact us for information on any future workshops and feel free to drop-in on our regular activity day to check out the group!', '2027-01-14'::date, '2027-01-14'::date, '13:00:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-basketry-group-at-the-rollo-centre-1896165', true),
  ('Contract Bridge at the Rollo Centre', 'We meet every Thursday afternoon at 1:30pm. There are anywhere from two to five tables (eight to twenty individuals) who play. Lately there have been four tables. A trophy for the highest score overall is given out. Cash prizes are given out for first and second place plus random cash prizes for card sequences. We enjoy a Christmas potluck lunch and party in December', '2027-01-14'::date, '2027-01-14'::date, '13:30:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/contract-bridge-at-the-rollo-centre-1885254', true),
  ('Spanish Conversation Group at the Gabriola Library', 'Drop in and practice your Spanish with the delightful Fernanda (Spanish is her first language), on Thursdays at the Gabriola Library from 3:30pm-4:30pm. Everyone is welcome!', '2027-01-14'::date, '2027-01-14'::date, '15:30:00'::time, '16:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/spanish-conversation-group-at-the-gabriola-library-1887233', true),
  ('Drumming at the Gabriola Arts Centre', '6pm - 7:30pm: Simple Rhythms - no experience needed.7:30pm - 9pm: Intermediate African Ensemble SongsEveryone is welcome, no charge, and some hand drums/balafons are provided. Located at the Gabriola Arts Centre', '2027-01-14'::date, '2027-01-14'::date, '18:00:00'::time, '21:00:00'::time, false, 'Gabriola Arts Council', 'Gabriola Arts Council', '476 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/drumming-at-the-gabriola-arts-centre-1884699', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2027-01-14'::date, '2027-01-14'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900701', true),
  ('Al-Anon Zoom Meeting', 'Al-Anon Zoom meeting through the Gabriola Fellowship Church on Thursday evenings from 7pm - 8pm', '2027-01-14'::date, '2027-01-14'::date, '19:00:00'::time, '20:00:00'::time, false, 'ZOOM', 'ZOOM', NULL, 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/al-anon-zoom-meeting-1901194', true),
