  ('Al-Anon Zoom Meeting', 'Al-Anon Zoom meeting through the Gabriola Fellowship Church on Thursday evenings from 7pm - 8pm', '2027-01-21'::date, '2027-01-21'::date, '19:00:00'::time, '20:00:00'::time, false, 'ZOOM', 'ZOOM', NULL, 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/al-anon-zoom-meeting-1901195', true),
